            return (RuleViolationFileNameStrategy) strategyType.getConstructor().newInstance();
        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException
                 | InvocationTargetException | ClassCastException | IllegalArgumentException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Could not instantiate RuleViolationFileNameStrategy configured by %s=%s; expected a public class "
                            + "with a public no-argument constructor",
                    FILE_NAMES_PROPERTY_NAME, value), e);
        }
    }

    private void prepareFolder(Path folder, boolean creationAllowed, File storedRulesFile) {
        try {
            if (!Files.exists(folder, NOFOLLOW_LINKS)) {
                if (!creationAllowed) {
                    throw new StoreInitializationFailedException(String.format(
                            "Creating new violation store is disabled (enable by configuration %s.%s=true)",
                            ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
                }
                Files.createDirectories(folder);
            }
            if (!Files.isDirectory(folder, NOFOLLOW_LINKS)) {
                throw new StoreInitializationFailedException(String.format(
                        "Violation store folder is not a directory: %s", folder));
            }
            if (storedRulesFile.toPath().getParent() == null
                    || !storedRulesFile.toPath().getParent().toAbsolutePath().normalize().equals(folder)) {
                throw new StoreInitializationFailedException(String.format("Invalid violation store path: %s", storedRulesFile));
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format("Cannot create violation store folder: %s", folder), e);
        }
    }

    private void createIndex(File storedRulesFile) {
        try {
            Files.createFile(storedRulesFile.toPath());
        } catch (FileAlreadyExistsException ignored) {
            // Another store may have created it while this store was waiting for a filesystem operation.
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    private void validateIndex(File storedRulesFile, Path folder) {
        Path index = storedRulesFile.toPath();
        if (!Files.isRegularFile(index, NOFOLLOW_LINKS)
                || index.getParent() == null
                || !index.getParent().toAbsolutePath().normalize().equals(folder)) {
            throw new StoreInitializationFailedException(String.format(
                    "The violation store index must be a regular file directly in the store folder: %s", index));
        }
    }

    private String canonicalStoreKey(File storedRulesFile) {
        try {
            return storedRulesFile.getCanonicalPath();
        } catch (IOException e) {
            return storedRulesFile.getAbsoluteFile().toPath().normalize().toString();
        }
    }

    private FileSyncedProperties getOrCreateStoredRules(File storedRulesFile) {
        try {
            return STORED_RULES_BY_PATH.computeIfAbsent(storedRulesFile.getCanonicalPath(),
                    ignored -> new FileSyncedProperties(storedRulesFile));
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
    }

    @Override
    public boolean contains(ArchRule rule) {
        synchronized (storedRules) {
            return storedRules.containsKey(rule.getDescription());
        }
    }

    @Override
    public void save(ArchRule rule, List<String> violations) {
        checkNotNull(rule);
        checkNotNull(violations);
        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
        if (!storeUpdateAllowed) {
            throw new StoreUpdateFailedException(String.format(
                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
        }

        synchronized (storedRules) {
            String ruleDescription = rule.getDescription();
            String existingFileName = storedRules.getProperty(ruleDescription);
            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
                if (existingFileName != null) {
                    forgetKnownRule(ruleDescription, existingFileName);
                }
                return;
            }

            String fileName = existingFileName != null ? existingFileName : createRuleFileName(ruleDescription);
            Path target = validateSaveTarget(ruleDescription, fileName);
            byte[] contents = encodedViolations(violations);
            boolean newlyCreated = existingFileName == null;
            try {
                writeViolationFile(ruleDescription, fileName, target, contents);
                if (newlyCreated) {
                    try {
                        storedRules.putIfAbsent(ruleDescription, fileName);
                    } catch (RuntimeException e) {
                        deleteQuietly(target);
                        throw e;
                    }
                }
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
    }

    private String createRuleFileName(String ruleDescription) {
        return checkedFileName(ruleViolationFileNameStrategy.createRuleFileName(ruleDescription), false);
    }

    private String checkedFileName(String fileName, boolean initialization) {
        if (fileName == null || fileName.trim().isEmpty()) {
            String message = "RuleViolationFileNameStrategy returned no file name";
            if (initialization) {
                throw new StoreInitializationFailedException(message);
            }
            throw new StoreUpdateFailedException(message);
        }
        return fileName;
    }

    private Path validateSaveTarget(String ruleDescription, String fileName) {
        Path indexPath = storeFolderPath.resolve(STORED_RULES_FILE_NAME).normalize();
        if (STORED_RULES_FILE_NAME.equals(fileName)
                || indexPath.equals(storeFolderPath.resolve(fileName).normalize())) {
            throw new StoreUpdateFailedException("A rule violation file cannot be named stored.rules");
        }
        Path recordedPath = storeFolderPath.resolve(fileName).normalize();
        if (!isDirectChild(recordedPath, storeFolderPath)) {
            throw new StoreUpdateFailedException(String.format(
                    "Refusing to write rule '%s' outside the violation store folder: %s", ruleDescription, fileName));
        }
        try {
            if (Files.exists(recordedPath, NOFOLLOW_LINKS)) {
                ResolvedPath resolved = resolvePath(fileName);
                if (!resolved.isUsable()) {
                    throw new StoreUpdateFailedException(String.format(
                            "Refusing to overwrite an unsafe violation file for rule '%s': %s", ruleDescription, fileName));
                }
                try {
                    if (sameFile(resolved.realPath, indexPath.toRealPath())) {
                        throw new StoreUpdateFailedException("A rule violation file cannot overwrite stored.rules");
                    }
                } catch (IOException e) {
                    throw new StoreUpdateFailedException(e);
                }
                String ownFileName = storedRules.getProperty(ruleDescription);
                boolean isRecordedByThisRule = fileName.equals(ownFileName)
                        || (ownFileName != null && isSameResolvedFile(ownFileName, resolved));
                if (!isRecordedByThisRule) {
                    throw new StoreUpdateFailedException(String.format(
                            "Refusing to overwrite a file not recorded by rule '%s': %s", ruleDescription, fileName));
                }
                return resolved.realPath;
            }
            return recordedPath;
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
    }

    private boolean isSameResolvedFile(String fileName, ResolvedPath resolved) {
        try {
            ResolvedPath ownPath = resolvePath(fileName);
            return ownPath.isUsable() && sameFile(resolved.realPath, ownPath.realPath);
        } catch (IOException ignored) {
            return false;
        }
    }

    private void writeViolationFile(String ruleDescription, String fileName, Path target, byte[] contents) throws IOException {
        Path temporary = Files.createTempFile(storeFolderPath, ".archunit-", ".tmp");
        try {
            Files.write(temporary, contents, StandardOpenOption.TRUNCATE_EXISTING);
            // Replacing the directory entry of a link would leave the link in place and write the wrong object.
            Path recordedPath = storeFolderPath.resolve(fileName).normalize();
            if (Files.isSymbolicLink(recordedPath) || hasOtherReference(target, fileName)) {
                Files.write(target, contents, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
            } else {
                moveReplacing(temporary, target);
                temporary = null;
            }
        } finally {
            if (temporary != null) {
                deleteQuietly(temporary);
            }
        }
    }

    private boolean hasOtherReference(Path target, String ownFileName) {
        for (String description : storedRules.keys()) {
            String recorded = storedRules.getProperty(description);
            if (recorded != null && !recorded.equals(ownFileName)) {
                try {
                    ResolvedPath other = resolvePath(recorded);
                    if (other.isUsable() && sameFile(target, other.realPath)) {
                        return true;
                    }
                } catch (IOException ignored) {
                    // Ignore an unrelated broken entry.
                }
            }
        }
        return false;
    }

    private byte[] encodedViolations(List<String> violations) {
        StringBuilder builder = new StringBuilder();
        for (String violation : violations) {
            builder.append(escape(checkNotNull(violation))).append("\n");
        }
        return builder.toString().getBytes(UTF_8);
    }

    private void forgetKnownRule(String description, String fileName) {
        ResolvedPath resolved;
        try {
            resolved = resolvePath(fileName);
        } catch (IOException e) {
            throw new StoreUpdateFailedException(e);
        }
        if (resolved.isUsable() && !sharedWithAnother(description, fileName, resolved)) {
            try {
                deleteResolvedFile(fileName, resolved);
            } catch (IOException e) {
                throw new StoreUpdateFailedException(new IOException(String.format(
                        "Cannot discard the violation file for rule '%s'", description), e));
            }
        }
        storedRules.remove(description);
    }

    private boolean sharedWithAnother(String description, String fileName, ResolvedPath resolved) {
        for (String otherDescription : storedRules.keys()) {
            if (description.equals(otherDescription)) {
                continue;
            }
            String otherName = storedRules.getProperty(otherDescription);
            if (fileName.equals(otherName)) {
                return true;
            }
            if (resolved.isUsable() && otherName != null) {
                try {
                    ResolvedPath other = resolvePath(otherName);
                    if (other.isUsable() && sameFile(resolved.realPath, other.realPath)) {
                        return true;
                    }
                } catch (IOException ignored) {
                    // A broken other entry cannot share a file which it cannot resolve.
                }
            }
        }
        return false;
    }

