    private String readStoreFile(String fileName) {
        try {
            String result = new String(toByteArray(storeFolderPath.resolve(fileName).toFile()), UTF_8);
            return ensureUnixLineBreaks(result);
        } catch (IOException e) {
            throw new StoreReadException(e);
        }
    }

    private String escape(String violation) {
        return violation.replace("\n", "\\\n");
    }

    private String unescape(String violation) {
        return violation.replace("\\\n", "\n");
    }

    private IntegrityAnalysis analyzeEmptyFolder(Path folder) {
        return new IntegrityAnalysis(Collections.emptyList(), directRegularFiles(folder));
    }

    private IntegrityAnalysis analyze(FileSyncedProperties rules, Path folder,
            RuleViolationFileNameStrategy strategy, boolean deterministicNames) {
        List<EntryAnalysis> entries = new ArrayList<>();
        for (String description : rules.keys()) {
            String recordedName = rules.getProperty(description);
            String derivedName = null;
            if (deterministicNames) {
                derivedName = checkedFileName(strategy.createRuleFileName(description), true);
            }
            ResolvedPath resolved;
            try {
                resolved = resolvePath(folder, recordedName);
            } catch (IOException e) {
                resolved = ResolvedPath.broken(recordedName, BrokenReason.MISSING);
            }
            boolean noViolations = resolved.isUsable() && hasNoViolations(resolved.realPath);
            entries.add(new EntryAnalysis(description, recordedName, derivedName, resolved, noViolations));
        }

        Map<String, List<EntryAnalysis>> recordedNames = groupByRecordedName(entries);
        Map<String, List<EntryAnalysis>> derivedNames = groupByDerivedName(entries);
        for (EntryAnalysis entry : entries) {
            entry.shared = recordedNames.get(entry.recordedName).size() > 1
                    || sharesResolvedFile(entry, entries);
            entry.misplaced = entry.derivedName != null && !entry.derivedName.equals(entry.recordedName);
            entry.colliding = entry.derivedName != null && derivedNames.get(entry.derivedName).size() > 1;
            entry.occupied = entry.misplaced && isOccupied(entry, entries, folder);
        }
        return new IntegrityAnalysis(entries, directRegularFiles(folder, entries));
    }

    private Map<String, List<EntryAnalysis>> groupByRecordedName(List<EntryAnalysis> entries) {
        Map<String, List<EntryAnalysis>> result = new HashMap<>();
        for (EntryAnalysis entry : entries) {
            result.computeIfAbsent(entry.recordedName, ignored -> new ArrayList<>()).add(entry);
        }
        return result;
    }

    private Map<String, List<EntryAnalysis>> groupByDerivedName(List<EntryAnalysis> entries) {
        Map<String, List<EntryAnalysis>> result = new HashMap<>();
        for (EntryAnalysis entry : entries) {
            if (entry.derivedName != null) {
                result.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
            }
        }
        return result;
    }

    private boolean sharesResolvedFile(EntryAnalysis entry, List<EntryAnalysis> entries) {
        if (!entry.resolved.isUsable()) {
            return false;
        }
        for (EntryAnalysis other : entries) {
            if (entry == other || !other.resolved.isUsable()) {
                continue;
            }
            try {
                if (sameFile(entry.resolved.realPath, other.resolved.realPath)) {
                    return true;
                }
            } catch (IOException ignored) {
                return false;
            }
        }
        return false;
    }

    private boolean isOccupied(EntryAnalysis entry, List<EntryAnalysis> entries, Path folder) {
        if (entry.derivedName.equals(entry.recordedName)) {
            return false;
        }
        Path derivedPath = folder.resolve(entry.derivedName).normalize();
        if (!isDirectChild(derivedPath, folder)) {
            return true;
        }
        for (EntryAnalysis other : entries) {
            if (other != entry && entry.derivedName.equals(other.recordedName)) {
                return true;
            }
        }
        return Files.exists(derivedPath, NOFOLLOW_LINKS);
    }

    private boolean hasNoViolations(Path resolvedFile) {
        try {
            String text = new String(Files.readAllBytes(resolvedFile), UTF_8);
            if (text.isEmpty() || text.matches("[\\r\\n]+")) {
                return true;
            }
            return readLinesFromText(text).isEmpty();
        } catch (IOException e) {
            return false;
        }
    }

    private List<String> readLinesFromText(String text) {
        return Splitter.on(UNESCAPED_LINE_BREAK_PATTERN).omitEmptyStrings().splitToStream(ensureUnixLineBreaks(text))
                .map(this::unescape)
                .collect(toList());
    }

    private List<String> directRegularFiles(Path folder) {
        return directRegularFiles(folder, Collections.emptyList());
    }

    private List<String> directRegularFiles(Path folder, List<EntryAnalysis> entries) {
        List<String> result = new ArrayList<>();
        try (DirectoryStream<Path> files = Files.newDirectoryStream(folder)) {
            for (Path file : files) {
                if (!STORED_RULES_FILE_NAME.equals(file.getFileName().toString())
                        && Files.isRegularFile(file, NOFOLLOW_LINKS)
                        && !isOwnedByEntry(file, entries)) {
                    result.add(file.getFileName().toString());
                }
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(e);
        }
        Collections.sort(result);
        return result;
    }

    private boolean isOwnedByEntry(Path file, List<EntryAnalysis> entries) {
        for (EntryAnalysis entry : entries) {
            if (entry.resolved.isUsable()) {
                try {
                    if (sameFile(file, entry.resolved.realPath)) {
                        return true;
                    }
                } catch (IOException ignored) {
                    // If the file cannot be compared, it remains reportable as unowned.
                }
            }
        }
        return false;
    }

    private void repair(IntegrityAnalysis analysis, FileSyncedProperties rules, Path folder) {
        boolean changed = false;
        for (EntryAnalysis entry : analysis.entriesInRuleOrder()) {
            if (entry.shared) {
                continue;
            }
            if (entry.resolved.isBroken()) {
                rules.removeWithoutSync(entry.description);
                changed = true;
            } else if (entry.noViolations) {
                try {
                    deleteResolvedFile(entry.recordedName, entry.resolved);
                } catch (IOException e) {
                    throw new StoreInitializationFailedException(String.format(
                            "Cannot discard resolved violation file '%s'", entry.recordedName), e);
                }
                rules.removeWithoutSync(entry.description);
                changed = true;
            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
                moveToDerivedName(entry, folder);
                rules.setWithoutSync(entry.description, entry.derivedName);
                changed = true;
            }
        }
        if (changed) {
            rules.sync();
        }
    }

    private void moveToDerivedName(EntryAnalysis entry, Path folder) {
        if (STORED_RULES_FILE_NAME.equals(entry.derivedName)) {
            throw new StoreInitializationFailedException("A rule violation file cannot be named stored.rules");
        }
        Path destination = folder.resolve(entry.derivedName).normalize();
        if (!isDirectChild(destination, folder) || Files.exists(destination, NOFOLLOW_LINKS)) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot move misplaced violation file '%s' to '%s'", entry.recordedName, entry.derivedName));
        }
        try {
            Path source = entry.resolved.realPath;
            if (sameFile(source, folder.resolve(STORED_RULES_FILE_NAME))) {
                throw new IOException("The index is not a movable violation file");
            }
            moveReplacing(source, destination);
            Path recordedPath = folder.resolve(entry.recordedName).normalize();
            if (!recordedPath.equals(source) && Files.exists(recordedPath, NOFOLLOW_LINKS)) {
                Files.delete(recordedPath);
            }
        } catch (IOException e) {
            throw new StoreInitializationFailedException(String.format(
                    "Cannot move misplaced violation file '%s' to '%s'", entry.recordedName, entry.derivedName), e);
        }
    }

    private void deleteResolvedFile(String recordedName, ResolvedPath resolved) throws IOException {
        if (!resolved.isUsable()) {
            return;
        }
        if (sameFile(resolved.realPath, storeFolderPath.resolve(STORED_RULES_FILE_NAME))) {
            throw new IOException("The index is not a deletable violation file");
        }
        Files.deleteIfExists(resolved.realPath);
        Path recordedPath = storeFolderPath.resolve(recordedName).normalize();
        if (!recordedPath.equals(resolved.realPath)) {
            Files.deleteIfExists(recordedPath);
        }
    }

    private ResolvedPath resolvePath(String fileName) throws IOException {
        return resolvePath(storeFolderPath, fileName);
    }

    private ResolvedPath resolvePath(Path folder, String fileName) throws IOException {
        if (fileName == null) {
            return ResolvedPath.broken(null, BrokenReason.MISSING);
        }
        Path recordedPath = folder.resolve(fileName).normalize();
        if (!Files.exists(recordedPath, NOFOLLOW_LINKS)) {
            return ResolvedPath.broken(fileName, BrokenReason.MISSING);
        }
        Path realPath = recordedPath.toRealPath();
        if (Files.isDirectory(realPath, NOFOLLOW_LINKS)) {
            return ResolvedPath.broken(fileName, BrokenReason.DIRECTORY);
        }
        if (!Files.isRegularFile(realPath, NOFOLLOW_LINKS)) {
            return ResolvedPath.broken(fileName, BrokenReason.NOT_REGULAR);
        }
        Path realFolder = folder.toRealPath();
        if (realPath.getParent() == null || !realPath.getParent().equals(realFolder)) {
            return ResolvedPath.broken(fileName, BrokenReason.OUTSIDE);
        }
        return ResolvedPath.usable(fileName, realPath);
    }

    private boolean isDirectChild(Path path, Path folder) {
        return path.getParent() != null && path.getParent().equals(folder);
    }

    private boolean sameFile(Path first, Path second) throws IOException {
        return Files.isSameFile(first, second);
    }

    private void moveReplacing(Path source, Path destination) throws IOException {
        try {
            Files.move(source, destination, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            Files.move(source, destination, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    private void deleteQuietly(Path path) {
        try {
            Files.deleteIfExists(path);
        } catch (IOException ignored) {
            log.debug("Could not remove temporary violation file {}", path);
        }
    }

    private static class FileSyncedProperties {
        private final File propertiesFile;
        private final Properties loadedProperties;

        FileSyncedProperties(File file) {
            propertiesFile = file;
            loadedProperties = loadRulesFrom(file);
        }

        private Properties loadRulesFrom(File file) {
            Properties result = new Properties();
            try (FileInputStream inputStream = new FileInputStream(file)) {
                result.load(inputStream);
            } catch (IOException e) {
                throw new StoreInitializationFailedException(e);
            }
            return result;
        }

        boolean containsKey(String propertyName) {
            return loadedProperties.containsKey(ensureUnixLineBreaks(propertyName));
        }

        String getProperty(String propertyName) {
            return loadedProperties.getProperty(ensureUnixLineBreaks(propertyName));
        }

        Set<String> keys() {
            Set<String> result = new HashSet<>();
            for (Object key : loadedProperties.keySet()) {
                result.add((String) key);
            }
            return result;
        }

        synchronized void putIfAbsent(String key, String value) {
            String normalizedKey = ensureUnixLineBreaks(key);
            if (loadedProperties.getProperty(normalizedKey) == null) {
                loadedProperties.setProperty(normalizedKey, ensureUnixLineBreaks(value));
                sync();
            }
        }

        void setWithoutSync(String key, String value) {
            loadedProperties.setProperty(ensureUnixLineBreaks(key), ensureUnixLineBreaks(value));
        }

        void removeWithoutSync(String key) {
            loadedProperties.remove(ensureUnixLineBreaks(key));
        }

        synchronized void remove(String key) {
            loadedProperties.remove(ensureUnixLineBreaks(key));
            sync();
        }

        synchronized void sync() {
            try {
                Properties snapshot = new Properties();
                snapshot.putAll(loadedProperties);
                Path temporary = Files.createTempFile(propertiesFile.toPath().getParent(), ".archunit-index-", ".tmp");
                try {
                    try (java.io.FileOutputStream outputStream = new java.io.FileOutputStream(temporary.toFile())) {
                        snapshot.store(outputStream, "");
                    }
                    try {
                        Files.move(temporary, propertiesFile.toPath(), StandardCopyOption.ATOMIC_MOVE,
                                StandardCopyOption.REPLACE_EXISTING);
                    } catch (IOException e) {
                        Files.move(temporary, propertiesFile.toPath(), StandardCopyOption.REPLACE_EXISTING);
                    }
                } finally {
                    Files.deleteIfExists(temporary);
                }
            } catch (IOException e) {
                throw new StoreUpdateFailedException(e);
            }
        }
    }

    private enum IntegrityMode { IGNORE, REPAIR, FAIL }

    private enum BrokenReason { MISSING, DIRECTORY, OUTSIDE, NOT_REGULAR }

    private static final class ResolvedPath {
        private final String recordedName;
        private final Path realPath;
        private final BrokenReason brokenReason;

        private ResolvedPath(String recordedName, Path realPath, BrokenReason brokenReason) {
            this.recordedName = recordedName;
            this.realPath = realPath;
            this.brokenReason = brokenReason;
        }

        static ResolvedPath usable(String recordedName, Path realPath) {
            return new ResolvedPath(recordedName, realPath, null);
        }

        static ResolvedPath broken(String recordedName, BrokenReason reason) {
            return new ResolvedPath(recordedName, null, reason);
        }

        boolean isUsable() {
            return brokenReason == null;
        }

        boolean isBroken() {
            return brokenReason != null;
        }
    }

    private final class EntryAnalysis {
        private final String description;
        private final String recordedName;
        private final String derivedName;
