    private final class IntegrityAnalysis {
        private final List<EntryAnalysis> entries;
        private final List<String> unownedFiles;

        private IntegrityAnalysis(List<EntryAnalysis> entries, List<String> unownedFiles) {
            this.entries = entries;
            this.unownedFiles = unownedFiles;
        }

        private List<EntryAnalysis> entriesInRuleOrder() {
            List<EntryAnalysis> result = new ArrayList<>(entries);
            result.sort(Comparator.comparing(entry -> entry.description));
            return result;
        }

        private boolean isClean() {
            return entries.stream().noneMatch(entry -> entry.resolved.isBroken() || entry.noViolations
                    || entry.shared || entry.misplaced || entry.colliding || entry.occupied)
                    && unownedFiles.isEmpty();
        }

        private String report() {
            StringBuilder result = new StringBuilder("Violation store integrity check failed:");
            appendEntries(result, "broken", entry -> entry.resolved.isBroken());
            appendEntries(result, "resolved", entry -> entry.noViolations);
            appendEntries(result, "shared", entry -> entry.shared);
            appendFiles(result, "unowned", unownedFiles);
            appendEntries(result, "misplaced", entry -> entry.misplaced);
            appendEntries(result, "colliding", entry -> entry.colliding);
            appendEntries(result, "occupied", entry -> entry.occupied);
            return result.toString();
        }

        private void appendEntries(StringBuilder result, String condition, EntryCondition predicate) {
            List<EntryAnalysis> matching = entries.stream().filter(predicate::matches)
                    .sorted(Comparator.comparing(entry -> entry.description))
                    .collect(toList());
            if (!matching.isEmpty()) {
                result.append('\n').append(condition).append(':');
                for (EntryAnalysis entry : matching) {
                    result.append("\n  ").append(entry.description).append(" -> ").append(entry.recordedName);
                    if (entry.derivedName != null && !entry.derivedName.equals(entry.recordedName)) {
                        result.append(" (derived ").append(entry.derivedName).append(')');
                    }
                }
            }
        }

        private void appendFiles(StringBuilder result, String condition, List<String> files) {
            if (!files.isEmpty()) {
                result.append('\n').append(condition).append(':');
                for (String file : files) {
                    result.append("\n  ").append(file);
                }
            }
        }
    }

    @FunctionalInterface
    private interface EntryCondition {
        boolean matches(EntryAnalysis entry);
    }

    private static class RandomFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            return UUID.randomUUID().toString();
        }
    }

    private static class DescriptionFileNameStrategy implements RuleViolationFileNameStrategy {
        @Override
        public String createRuleFileName(String ruleDescription) {
            String word = null;
            Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(ruleDescription);
            while (matcher.find()) {
                String candidate = matcher.group();
                if (candidate.length() >= 4 && candidate.length() <= 120) {
                    word = candidate;
                }
            }
            if (word == null) {
                word = "rule";
            }
            return word + "-" + digest(ruleDescription);
        }

        private String digest(String value) {
            try {
                byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
                StringBuilder result = new StringBuilder();
                for (byte part : digest) {
                    result.append(String.format("%02x", part & 0xff));
                }
                return result.toString();
            } catch (NoSuchAlgorithmException e) {
                throw new AssertionError(e);
            }
        }
